// ===== Code Review Analyzer =====
// Input (webhook body): { files: [{ path, content }], options?: { minSeverity: 'low'|'medium'|'high'|'critical' } }
const SEV = { critical: 4, high: 3, medium: 2, low: 1 };
const items = $input.all();
const files = [];
let minSeverity = 'low';

for (const item of items) {
  const body = item.json.body || item.json;
  if (body.options && SEV[body.options.minSeverity]) minSeverity = body.options.minSeverity;
  for (const f of (body.files || [])) files.push(f);
}

// ---------- helpers ----------
// Blank out comments (and optionally string contents) but keep length + newlines,
// so indexes and line numbers still match the original source.
function mask(src, maskStrings) {
  let out = '';
  const comments = [];
  const n = src.length;
  let i = 0;
  while (i < n) {
    const c = src[i], d = src[i + 1];
    if (c === '/' && d === '/') {
      let j = i;
      while (j < n && src[j] !== '\n') j++;
      comments.push({ text: src.slice(i, j), index: i });
      out += ' '.repeat(j - i);
      i = j;
      continue;
    }
    if (c === '/' && d === '*') {
      let j = src.indexOf('*/', i + 2);
      j = j === -1 ? n : j + 2;
      const seg = src.slice(i, j);
      comments.push({ text: seg, index: i });
      out += seg.replace(/[^\n]/g, ' ');
      i = j;
      continue;
    }
    if (c === '"' || c === "'" || c === '`') {
      let j = i + 1;
      while (j < n) {
        if (src[j] === '\\') { j += 2; continue; }
        if (src[j] === c) break;
        if (c !== '`' && src[j] === '\n') break;
        j++;
      }
      const closed = src[j] === c;
      const end = closed ? j + 1 : j;
      const seg = src.slice(i, end);
      if (maskStrings) {
        const inner = closed ? seg.slice(1, -1) : seg.slice(1);
        out += c + inner.replace(/[^\n]/g, ' ') + (closed ? c : '');
      } else {
        out += seg;
      }
      i = end;
      continue;
    }
    out += c;
    i++;
  }
  return { masked: out, comments };
}

function makeLineFinder(text) {
  const starts = [0];
  for (let i = 0; i < text.length; i++) if (text[i] === '\n') starts.push(i + 1);
  return (idx) => {
    let lo = 0, hi = starts.length - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (starts[mid] <= idx) lo = mid; else hi = mid - 1;
    }
    return lo + 1;
  };
}

function matchClose(text, openIdx) {
  const open = text[openIdx];
  const close = { '{': '}', '(': ')', '[': ']' }[open];
  let depth = 0;
  for (let i = openIdx; i < text.length; i++) {
    if (text[i] === open) depth++;
    else if (text[i] === close) { depth--; if (depth === 0) return i; }
  }
  return -1;
}

function hasTopLevelComma(text) {
  let d = 0;
  for (const ch of text) {
    if ('({['.includes(ch)) d++;
    else if (')}]'.includes(ch)) d--;
    else if (ch === ',' && d === 0) return true;
  }
  return false;
}

// ---------- simple regex rules ----------
// view: 'code' = comments + strings blanked | 'text' = comments blanked, strings kept
const RULES = [
  // --- bugs ---
  { rule: 'loose-equality', sev: 'medium', cat: 'bug', view: 'code',
    re: /(?<![=!<>])(?:==|!=)(?!=)(?!\s*null\b)/g,
    msg: 'Loose equality (==, !=) — use === / !== to avoid type-coercion bugs' },
  { rule: 'assignment-in-condition', sev: 'high', cat: 'bug', view: 'code',
    re: /\b(?:if|while)\s*\(\s*[\w$.\[\]]+\s*=(?![=>])/g,
    msg: 'Assignment (=) inside a condition — probably meant ===' },
  { rule: 'nan-compare', sev: 'high', cat: 'bug', view: 'code',
    re: /(?:[=!]==?\s*NaN\b|\bNaN\s*[=!]==?)/g,
    msg: 'Comparing with NaN never works — use Number.isNaN()' },
  { rule: 'typeof-typo', sev: 'high', cat: 'bug', view: 'text',
    re: /typeof\s+[\w$.\[\]]+\s*[=!]==?\s*(['"`])(?!(?:undefined|string|number|boolean|object|function|symbol|bigint)\1)[^'"`]*\1/g,
    msg: 'typeof compared with an invalid type string (typo?) — condition is always the same' },
  { rule: 'useeffect-async', sev: 'high', cat: 'bug', view: 'code',
    re: /\buse(?:Layout)?Effect\s*\(\s*async\b/g,
    msg: 'useEffect callback cannot be async — it returns a Promise instead of a cleanup function' },
  { rule: 'await-in-loop', sev: 'low', cat: 'quality', view: 'code',
    re: /\b(?:for|while)\s*\((?:(?!\bawait\b)[^{])*\{[^}]*\bawait\b/g,
    msg: 'await inside a loop runs sequentially — consider Promise.all if the calls are independent' },

  // --- silent bugs (fail without any visible error) ---
  { rule: 'async-foreach', sev: 'high', cat: 'silent_bug', view: 'code',
    re: /\.forEach\s*\(\s*async\b/g,
    msg: 'async callback in forEach is not awaited — code after it runs early and errors are lost (use for...of or Promise.all)' },
  { rule: 'empty-catch-callback', sev: 'high', cat: 'silent_bug', view: 'code',
    re: /\.catch\s*\(\s*(?:\([^)]*\)|\w+)?\s*=>\s*(?:\{\s*\}|null|undefined|\[\s*\]|false)\s*\)/g,
    msg: '.catch() swallows the error and does nothing' },

  // --- security ---
  { rule: 'hardcoded-secret', sev: 'critical', cat: 'security', view: 'text',
    re: /(?:api[_-]?key|secret|token|password|passwd|private[_-]?key)\w*\s*[:=]\s*(['"`])[^'"`\s]{8,}\1/gi,
    msg: 'Hardcoded secret/token — move it to an environment variable' },
  { rule: 'hardcoded-jwt', sev: 'high', cat: 'security', view: 'text',
    re: /['"`]eyJ[\w-]{20,}\.[\w-]{20,}\.[\w-]{10,}['"`]/g,
    msg: 'Hardcoded JWT/key (if it is a Supabase service_role key this is critical) — use env variables' },
  { rule: 'eval', sev: 'high', cat: 'security', view: 'code',
    re: /\beval\s*\(|new\s+Function\s*\(/g,
    msg: 'eval / new Function executes arbitrary code' },
  { rule: 'inner-html', sev: 'medium', cat: 'security', view: 'code',
    re: /\.innerHTML\s*=|dangerouslySetInnerHTML/g,
    msg: 'Raw HTML injection — XSS risk unless the content is sanitized' },

  // --- quality ---
  { rule: 'debugger', sev: 'medium', cat: 'quality', view: 'code', re: /\bdebugger\b/g,
    msg: 'debugger statement left in code' },
  { rule: 'console', sev: 'low', cat: 'quality', view: 'code',
    re: /\bconsole\.(?:log|debug|info|warn|error|trace)\s*\(/g,
    msg: 'console statement — remove before production' },
  { rule: 'var', sev: 'low', cat: 'quality', view: 'code', re: /\bvar\s+[\w$]/g,
    msg: 'var — use let/const' },
  { rule: 'ts-any', sev: 'low', cat: 'quality', view: 'code', tsOnly: true,
    re: /(?::\s*any\b|\bas\s+any\b|<any>)/g,
    msg: 'Explicit any — disables type checking here' },
];

// ---------- per-file analysis ----------
function analyze(file) {
  const filePath = file.path || file.filePath || 'unknown';
  const fileName = filePath.split('/').pop();
  if (!/\.(ts|tsx|js|jsx|mjs|cjs)$/.test(fileName)) return null;
  const isTS = /\.tsx?$/.test(fileName);
  const src = String(file.content || '');

  const { masked: code, comments } = mask(src, true);
  const text = mask(src, false).masked;
  const lineAt = makeLineFinder(src);
  const srcLines = src.split('\n');

  const findings = [];
  const seen = new Set();
  const add = (line, severity, category, rule, message) => {
    const key = rule + ':' + line;
    if (seen.has(key)) return;
    seen.add(key);
    findings.push({
      line, severity, category, rule, message,
      snippet: (srcLines[line - 1] || '').trim().slice(0, 160),
    });
  };

  // 1) regex rules
  for (const r of RULES) {
    if (r.tsOnly && !isTS) continue;
    const view = r.view === 'text' ? text : code;
    const re = new RegExp(r.re.source, r.re.flags);
    let m;
    while ((m = re.exec(view))) {
      add(lineAt(m.index), r.sev, r.cat, r.rule, r.msg);
      if (m[0].length === 0) re.lastIndex++;
    }
  }

  // 2) catch blocks: empty / log-only / returns default  => silent bugs
  const catchRe = /\bcatch\s*(?:\(([^)]*)\))?\s*\{/g;
  let m;
  while ((m = catchRe.exec(code))) {
    const open = m.index + m[0].length - 1;
    const close = matchClose(code, open);
    if (close < 0) continue;
    const body = code.slice(open + 1, close);
    const line = lineAt(m.index);
    const rest = body.replace(/console\.\w+\s*\([^;]*\)\s*;?/g, '').trim();
    if (body.trim() === '') {
      add(line, 'high', 'silent_bug', 'empty-catch', 'Empty catch block (even if it only has a comment) — errors are swallowed silently');
    } else if (rest === '') {
      add(line, 'high', 'silent_bug', 'log-only-catch', 'catch only logs the error — the caller / UI never learns it failed');
    } else if (/^return\s*(?:null|undefined|false|true|0|\[\s*\]|\{\s*\}|''|""|``)?\s*;?$/.test(rest)) {
      add(line, 'medium', 'silent_bug', 'catch-returns-default', 'catch swallows the error and returns a default value — failure looks like success');
    }
  }

  // 3) React effects: missing deps / missing cleanup
  const effRe = /\buse(?:Layout)?Effect\s*\(/g;
  while ((m = effRe.exec(code))) {
    const open = m.index + m[0].length - 1;
    const close = matchClose(code, open);
    if (close < 0) continue;
    const args = code.slice(open + 1, close);
    const line = lineAt(m.index);
    if (!hasTopLevelComma(args)) {
      add(line, 'medium', 'bug', 'effect-no-deps', 'useEffect has no dependency array — runs after every render');
    }
    if (/addEventListener\s*\(|setInterval\s*\(|\.subscribe\s*\(|onAuthStateChange\s*\(|\.channel\s*\(/.test(args) &&
        !/\breturn\s*(?:\(\s*\)\s*=>|function\b|[\w$.]+\s*;)/.test(args)) {
      add(line, 'medium', 'silent_bug', 'effect-no-cleanup', 'useEffect creates a listener/timer/subscription but returns no cleanup — leaks and duplicate handlers');
    }
  }

  // 4) async .map without Promise.all
  const mapRe = /\.map\s*\(\s*async\b/g;
  while ((m = mapRe.exec(code))) {
    const before = code.slice(Math.max(0, m.index - 120), m.index);
    if (!/Promise\.(?:all|allSettled|race|any)/.test(before)) {
      add(lineAt(m.index), 'medium', 'silent_bug', 'async-map-unawaited', 'async .map() returns an array of Promises that is never awaited (wrap with Promise.all)');
    }
  }

  // 5) fetch() without checking the response
  const fm = /\bfetch\s*\(/.exec(code);
  if (fm && !/\.ok\b|\.status\b/.test(code)) {
    add(lineAt(fm.index), 'medium', 'silent_bug', 'fetch-no-status-check', 'fetch() response is never checked (.ok / .status) — HTTP 4xx/5xx is treated as success');
  }

  // 6) Supabase: ignoring `error`
  const sbRe = /(?:const|let)\s*\{([^}]*)\}\s*=\s*await\s+[\w$.]*supabase[\w$]*/gi;
  while ((m = sbRe.exec(code))) {
    if (!/\berror\b/.test(m[1])) {
      add(lineAt(m.index), 'medium', 'silent_bug', 'supabase-error-ignored', 'Supabase result destructured without `error` — a failed query silently gives data = null');
    }
  }
  const sbDiscard = /^[ \t]*await\s+[\w$.]*supabase[\w$]*\s*\.\s*from\b/gim;
  while ((m = sbDiscard.exec(code))) {
    add(lineAt(m.index), 'medium', 'silent_bug', 'supabase-result-discarded', 'Supabase call result is discarded — errors are never checked');
  }

  // 7) unreachable code after return / throw
  const L = code.split('\n');
  const bal = (s, a, b) => s.split(a).length === s.split(b).length;
  for (let i = 0; i < L.length; i++) {
    const t = L[i].trim();
    if (!/^(?:return|throw)\b/.test(t) || !t.endsWith(';')) continue;
    if (!bal(t, '(', ')') || !bal(t, '{', '}') || !bal(t, '[', ']')) continue;
    let p = i - 1;
    while (p >= 0 && L[p].trim() === '') p--;
    if (p >= 0 && /(?:\)|\belse|=>)\s*$/.test(L[p].trim())) continue;
    let n = i + 1;
    while (n < L.length && L[n].trim() === '') n++;
    if (n >= L.length) continue;
    if (/^(?:\}|\)|\]|case\b|default\b|else\b)/.test(L[n].trim())) continue;
    add(n + 1, 'medium', 'bug', 'unreachable-code', 'Unreachable code after return/throw');
  }

  // 8) unbalanced brackets => likely syntax error
  for (const [o, c] of [['{', '}'], ['(', ')'], ['[', ']']]) {
    const a = code.split(o).length - 1, b = code.split(c).length - 1;
    if (a !== b) add(1, 'medium', 'bug', 'unbalanced-brackets', `Unbalanced ${o}${c}: ${a} opening vs ${b} closing — possible syntax error`);
  }

  // 9) comments: lint/ts suppression, TODOs
  for (const c of comments) {
    const line = lineAt(c.index);
    if (/@ts-ignore|@ts-nocheck|eslint-disable/.test(c.text)) {
      add(line, 'medium', 'silent_bug', 'suppressed-check', 'Compiler/lint check is suppressed — a real problem may be hidden here');
    }
    if (/\b(?:TODO|FIXME|HACK|XXX)\b/.test(c.text)) {
      add(line, 'low', 'quality', 'todo', 'Unfinished work marker (TODO/FIXME/HACK)');
    }
  }

  // ---------- finalize ----------
  const filtered = findings
    .filter((f) => SEV[f.severity] >= SEV[minSeverity])
    .sort((a, b) => a.line - b.line || SEV[b.severity] - SEV[a.severity]);

  const counts = { critical: 0, high: 0, medium: 0, low: 0 };
  for (const f of filtered) counts[f.severity]++;
  const status = counts.critical + counts.high > 0 ? 'fail' : filtered.length ? 'warn' : 'clean';

  return { filePath, fileName, status, counts, findings: filtered };
}

// ---------- run ----------
const reports = [];
const skipped = [];
for (const f of files) {
  const r = analyze(f);
  if (r) reports.push(r); else skipped.push(f.path || f.filePath || 'unknown');
}

const bySeverity = { critical: 0, high: 0, medium: 0, low: 0 };
const byCategory = { bug: 0, silent_bug: 0, security: 0, quality: 0 };
for (const r of reports) for (const f of r.findings) { bySeverity[f.severity]++; byCategory[f.category]++; }
const totalFindings = reports.reduce((s, r) => s + r.findings.length, 0);
const passed = bySeverity.critical + bySeverity.high === 0;

const icon = { fail: '❌', warn: '⚠️', clean: '✅' };
const lines = [];
for (const r of reports) {
  lines.push(`${icon[r.status]} ${r.filePath}  (${r.findings.length} issue${r.findings.length === 1 ? '' : 's'})`);
  for (const f of r.findings) {
    lines.push(`   L${f.line}  [${f.severity.toUpperCase()}/${f.category}] ${f.message}`);
  }
}

return [{
  json: {
    passed,
    summary: {
      totalFiles: reports.length,
      filesWithIssues: reports.filter((r) => r.findings.length).length,
      totalFindings,
      bySeverity,
      byCategory,
      skippedNonCodeFiles: skipped,
    },
    files: reports,
    report: lines.join('\n') || 'No JS/TS files received.',
  },
}];
